              [False, False],
          ]),
          sop=rasp.ConstantSOp(["h", "e"]),
          default=None,
          expected_value=["h", None],
      ),
      dict(
          selector=rasp.ConstantSelector([
              [True, True],
              [False, True],
          ]),
          sop=rasp.ConstantSOp([0, 1]),
