def has_prev(seq: rasp.SOp) -> rasp.SOp:
      prev_copy = rasp.SelectorAnd(
          rasp.Select(seq, seq, rasp.Comparison.EQ),
          rasp.Select(rasp.indices, rasp.indices, rasp.Comparison.LT),
      )
