def test_identity_from_action(self):
    vs = bases.VectorSpaceWithBasis.from_names(["a", "b", "c"])
    f = vs_fns.Linear.from_action(vs, vs, vs.vector_from_basis_direction)
    for v in vs.basis_vectors():
