def get_layer_id(self, layer_name):
        # https://github.com/microsoft/unilm/blob/master/beit/optim_factory.py#L33
        num_layers = self.get_num_layers()
        if layer_name in ["cls_token", "pos_embed"]:
            return 0
        elif layer_name.find("patch_embed") != -1:
            return 0
        elif layer_name.find("blocks") != -1:
            return int(layer_name.split("blocks")[1].split(".")[1]) + 1
        else:
            return num_layers

@param_groups.setter
def param_groups(self, value):
        self.optim.param_groups = value

def _get_video_object(self, path):
        return EncodedVideo.from_path(
            path, decoder=self.decoder, decode_audio=False, **self.decoder_kwargs
        )

def _get_path(self, idx):
        path = self._replace_path_prefix(
            self.paths[idx],
            replace_prefix=self.remove_prefix,
            new_prefix=self.new_prefix,
        )
        path = self._replace_path_suffix(
            path, replace_suffix=self.remove_suffix, new_suffix=self.new_suffix
        )
        return path

def get_pred_ratio(pred_ratio, pred_ratio_var):
    if isinstance(pred_ratio, list):
        curr_pred_ratio = []
        for prm, prv in zip(pred_ratio, pred_ratio_var):
            assert prm >= prv
            pr = random.uniform(prm - prv, prm + prv) if prv > 0 else prm
            curr_pred_ratio.append(pr)
        curr_pred_ratio = random.choice(curr_pred_ratio)
    else:
        assert pred_ratio >= pred_ratio_var
        curr_pred_ratio = (
            random.uniform(
                pred_ratio - pred_ratio_var,
                pred_ratio + pred_ratio_var,
            )
            if pred_ratio_var > 0
            else pred_ratio
        )
    return curr_pred_ratio

def get_patch_embedding(self, x):
        # x: B x C x T x H x W
        assert x.ndim == 5
        has_depth = x.shape[1] == 4

        if has_depth:
            if self.depth_mode in ["summed_rgb_d_tokens"]:
                x_rgb = x[:, :3, ...]
                x_d = x[:, 3:, ...]
                x_d = self.depth_patch_embed(x_d)
                x_rgb = self.patch_embed(x_rgb)
                # sum the two sets of tokens
                x = x_rgb + x_d
            elif self.depth_mode == "rgbd":
                if self.depth_patch_embed_separate_params:
                    x = self.depth_patch_embed(x)
                else:
                    x = self.patch_embed(x)
            else:
                logging.info("Depth mode %s not supported" % self.depth_mode)
                raise NotImplementedError()
        else:
            x = self.patch_embed(x)
        return x

def get_window_size(x_size, window_size, shift_size=None):
    use_window_size = list(window_size)
    if shift_size is not None:
        use_shift_size = list(shift_size)
    for i in range(len(x_size)):
        if x_size[i] <= window_size[i]:
            use_window_size[i] = x_size[i]
            if shift_size is not None:
                use_shift_size[i] = 0

    if shift_size is None:
        return tuple(use_window_size)
    else:
        return tuple(use_window_size), tuple(use_shift_size)

@property
def param_groups(self):
        return self.optim.param_groups

def get_sample(self):
        sample = {}
        """
        grad_accum_sample = False
        """
        for idx in range(len(self.iterators)):
            if not self.source_to_use[idx, self.step_counter]:
                continue
            try:
                val = next(self.iterators[idx])
            except StopIteration:
                self.iterators[idx] = iter(self.dataloaders[idx])
                val = next(self.iterators[idx])

            self.per_src_step_counter[idx] += 1
            if self.per_src_step_counter[idx] > self.iterator_lens[idx]:
                raise ValueError(
                    f"Something is off. For iterator {idx} expected {self.iterator_lens[idx]} steps but currently at {self.per_src_step_counter[idx]}"
                )

            """
            if GradAccumSampleHandler.is_grad_accum_sample(val):
                vals = GradAccumSampleHandler.strip_grad_accum_sentinel(val)
                if isinstance(sample, dict):
                    # now `sample` is a dict which we want to make a list of dictionaries
                    sample = [{x: sample[x]} for x in sample]
                sample.extend([{output_key: val} for val in vals])
                grad_accum_sample = True
            elif grad_accum_sample:
                # now `val` is a dict which we will append to the sample list
                assert isinstance(sample, list)
                sample.append({output_key: val})
            else:
                # grad accum isn't on, simply create a dictionary
                sample[output_key] = val
            """
            orig_keys = len(sample)
            sample.update(val)
            assert len(sample) == orig_keys + len(val)

        """
        if grad_accum_sample:
            return GradAccumSampleHandler.add_grad_accum_sentinel(sample)
        """
        return sample

def _check_valid(self, param_groups, expected_values):
        for param_group in param_groups:
            self.assertTrue(
                set(["lr", "weight_decay", "params"]).issubset(set(param_group.keys()))
            )
            lr = np.round(param_group["lr"], 2)
            wd = np.round(param_group["weight_decay"], 2)
            self.assertEqual(expected_values[lr][wd], set(param_group["params"]))

def auto_augment_policy(name="v0", hparams=None):
    hparams = hparams or _HPARAMS_DEFAULT
    if name == "original":
        return auto_augment_policy_original(hparams)
    elif name == "originalr":
        return auto_augment_policy_originalr(hparams)
    elif name == "v0":
        return auto_augment_policy_v0(hparams)
    elif name == "v0r":
        return auto_augment_policy_v0r(hparams)
    else:
        assert AssertionError, "Unknown AA policy (%s)" % name

def get_amp_type(amp_type: str):

    assert amp_type in ["bfloat16", "float16"], "Invalid Amp type."

    if amp_type == "bfloat16":
        return torch.bfloat16
    else:
        return torch.float16

def get_position_angle_vec(position):
        return [
            position / np.power(10000, 2 * (hid_j // 2) / d_hid)
            for hid_j in range(d_hid)
        ]

