        d = self.domain_discriminator(f)
        d_s, d_t = d.chunk(2, dim=0)
        d_label_s = torch.ones((f_s.size(0), 1)).to(f_s.device)
        d_label_t = torch.zeros((f_t.size(0), 1)).to(f_t.device)
        self.domain_discriminator_accuracy = 0.5 * (
            binary_accuracy(d_s, d_label_s) + binary_accuracy(d_t, d_label_t)
        )
        return 0.5 * (self.bce(d_s, d_label_s) + self.bce(d_t, d_label_t))

def forward(self, z_s: torch.Tensor, z_t: torch.Tensor) -> torch.Tensor:
        features = torch.cat([z_s, z_t], dim=0)
        batch_size = int(z_s.size(0))
        self.index_matrix = _update_index_matrix(
            batch_size, self.index_matrix, self.linear
        ).to(z_s.device)

        if not self.quadratic_program:
            kernel_matrix = sum(
                [kernel(features) for kernel in self.kernels]
            )  # Add up the matrix of each kernel
            # Add 2 / (n-1) to make up for the value on the diagonal
