            loss = (kernel_matrix * self.index_matrix).sum() + 2.0 / float(
                batch_size - 1
            )
        else:
            kernel_values = [
                (kernel(features) * self.index_matrix).sum()
                + 2.0 / float(batch_size - 1)
                for kernel in self.kernels
            ]
            loss = optimal_kernel_combinations(kernel_values)
        return loss

