        self.domain_discriminator_accuracy = 0.5 * (
            binary_accuracy(d_s, d_label_s) + binary_accuracy(d_t, d_label_t)
        )
        return 0.5 * (self.bce(d_s, d_label_s) + self.bce(d_t, d_label_t))

def zero_grad(self):
        """
        Set gradients for trainable parameters for the current problem to 0.
        Similar with PyTorch's ``optim.zero_grad()`` or ``module.zero_grad()``.
        """
        for param in list(self.trainable_parameters()):
            if hasattr(param, "grad"):
                del param.grad

def reg_loss(parameters, reference_parameters, reg_lambda=0.25):
    loss = 0
    for p1, p2 in zip(parameters, reference_parameters):
        loss += torch.sum(torch.pow((p1 - p2), 2))

    return reg_lambda * loss

def forward(
        self,
        y_s: torch.Tensor,
        y_s_adv: torch.Tensor,
        y_t: torch.Tensor,
        y_t_adv: torch.Tensor,
    ) -> torch.Tensor:
        _, prediction_s = y_s.max(dim=1)
        _, prediction_t = y_t.max(dim=1)
        return self.margin * F.cross_entropy(
            y_s_adv, prediction_s, reduction=self.reduction
        ) + F.nll_loss(
            shift_log(1.0 - F.softmax(y_t_adv, dim=1)),
            prediction_t,
            reduction=self.reduction,
        )

def zero_gradients(i):
    for t in iter_gradients(i):
        t.zero_()

def training_step(self, batch):
        inputs, labels = batch
        out = self.inner(inputs)
        loss = F.cross_entropy(out, labels)
        acc = 100.0 * (out.argmax(dim=1) == labels).float().mean().item()

        return {"loss": loss, "acc": acc}

