def test_set_problem_attr(self):
        self.assertTrue(hasattr(self.engine, "inner"))
        self.assertTrue(hasattr(self.engine, "outer"))

def set_epoch(self, epoch):
        self.epoch = epoch

        if self.generator is not None:
            self.generator.manual_seed(self.seed + self.epoch)

def set_grads(self, params, grads):
        """
        Set gradients for trainable parameters. ``params.grad = grads``

        :param params: Trainable parameters
        :type params: Sequence of Tensor
        :param grads: Calculated gradient
        :type grads: Sequence of Tensor
        """
        for param, grad in zip(params, grads):
            if grad is not None:
                if hasattr(param, "grad") and param.grad is not None:
                    param.grad = param.grad + grad
                else:
                    param.grad = grad

def training_step(self, batch):
        inputs, labels = batch
        out = self.inner(inputs)
        loss = F.cross_entropy(out, labels)
        acc = 100.0 * (out.argmax(dim=1) == labels).float().mean().item()

        return {"loss": loss, "acc": acc}

def add_word(self, word):
        if not word in self.word2idx:
            self.word2idx[word] = self.idx
            self.idx2word[self.idx] = word
            self.idx += 1

def _loss(self, input, target):
        logits = self(input)
        return self._criterion(logits, target)

