def conv1x1(in_planes, out_planes, stride=1):
    """1x1 convolution"""
    return nn.Conv2d(in_planes, out_planes, kernel_size=1, stride=stride, bias=False)

def assign_splits(imgs, params):
    num_val = params["num_val"]
    num_test = params["num_test"]

    for i, img in enumerate(imgs):
        if i < num_val:
            img["split"] = "val"
        elif i < num_val + num_test:
            img["split"] = "test"
        else:
            img["split"] = "train"

    print("assigned %d to val, %d to test." % (num_val, num_test))

def set_grads(self, params, grads):
        """
        Set gradients for trainable parameters. ``params.grad = grads``

        :param params: Trainable parameters
        :type params: Sequence of Tensor
        :param grads: Calculated gradient
        :type grads: Sequence of Tensor
        """
        for param, grad in zip(params, grads):
            if grad is not None:
                if hasattr(param, "grad") and param.grad is not None:
                    param.grad = param.grad + grad
                else:
                    param.grad = grad

def step(self, params):
        for param_group, param_mapping in zip(self.param_groups, self.param_mappings):
            amsgrad = param_group["amsgrad"]
            beta1, beta2 = param_group["betas"]

            for param_idx in param_mapping:
                p = params[param_idx]

                if p.grad is None:
                    continue
                grad = p.grad

                p = p * (1 - param_group["lr"] * param_group["weight_decay"])
                state = self.state[param_idx]

                state["step"] += 1
                bias_correction1 = 1 - beta1 ** state["step"]
                bias_correction2 = 1 - beta2 ** state["step"]

                state["exp_avg"] = state["exp_avg"] * beta1 + (1 - beta1) * grad
                state["exp_avg_sq"] = (
                    state["exp_avg_sq"] * beta2 + (1 - beta2) * grad * grad
                )

                if amsgrad:
                    state["max_exp_avg_sq"] = torch.max(
                        state["max_exp_avg_sq"], state["exp_avg_sq"]
                    )
                    denom = (
                        state["max_exp_avg_sq"] / math.sqrt(bias_correction2)
                        + param_group["eps"]
                    )
                else:
                    denom = (
                        state["exp_avg_sq"] / math.sqrt(bias_correction2)
                        + param_group["eps"]
                    )

                step_size = param_group["lr"] / bias_correction1
                p.update = step_size * (state["exp_avg"] / denom)

        new_params = tuple(p - p.update for p in params if hasattr(p, "update"))
        for p in params:
            if hasattr(p, "update"):
                del p.update

        return new_params

