def logger(logger_type="none"):
    logger_type = type_check(logger_type)
    return logger_mapping[logger_type]()

def type_check(logger_type):
    assert logger_type in logger_mapping

    if logger_type == "wandb":
        try:
            import wandb
        except ImportError:
            get_logger().warning(
                "[!] WandB is not installed. The default logger will be instead used."
            )
            logger_type = "none"
    elif logger_type == "tensorboard":
        try:
            from torch.utils.tensorboard import SummaryWriter
        except ImportError:
            get_logger().warning(
                "[!] Tensorboard is not installed. The default logger will be instead used."
            )
            logger_type = "none"

    return logger_type

def get_batch(self):
        inputs, labels = self.env.batch["train"]

        return inputs, labels

def get_batch(self):
        inputs, labels = self.env.batch["test"]

        return inputs, labels

def get_lr(opt):
    """
    get the learning rate
    """
    for param_group in opt.param_groups:
        return param_group["lr"]

def log_from_loss_dict(loss_dict):
    outputs = []
    for key, values in loss_dict.items():
        if isinstance(values, dict) or isinstance(values, list):
            for value_idx, value in enumerate(values):
                full_key = key + "_" + str(value_idx)
                if torch.is_tensor(value):
                    value = value.item()
                output = f"{full_key}: {value}"
                outputs.append(output)
        else:
            if torch.is_tensor(values):
                values = values.item()
            output = f"{key}: {values}"
            outputs.append(output)
    return " || ".join(outputs)

def get_multiplier(problem):
    if problem.leaf:
        return 1

    assert len(problem.children) > 0
    # stack to store all the nodes of tree
    s1 = []
    # stack to store all the leaf nodes
    s2 = []

    s1.append((problem, 1))
    while len(s1) != 0:
        curr, multiplier = s1.pop(0)

        if len(curr.children) != 0:
            for child in curr.children:
                s1.append((child, multiplier * curr.config.step))
        else:
            s2.append(multiplier)

    assert all(x == s2[0] for x in s2)
    return s2[0]

def get_optimzer_type(optimizer):
    cls_name = type(optimizer).__name__.lower()
    if "adam" in cls_name:
        return "adam"
    return "sgd"

def get_weight_norm(parameters):
    if isinstance(parameters, torch.Tensor):
        parameters = [parameters]

    total_norm = 0.0
    for p in parameters:
        param_norm = torch.norm(p, dtype=torch.float32)
        total_norm += param_norm.item() ** 2

    if (
        total_norm == float("inf")
        or total_norm == -float("inf")
        or total_norm != total_norm
    ):
        total_norm = -1

    return total_norm

def get_grad_norm(parameters):
    if isinstance(parameters, torch.Tensor):
        parameters = [parameters]
    parameters = list(filter(lambda p: p.grad is not None, parameters))

    total_norm = 0.0
    for p in parameters:
        param_norm = p.grad.data.float().norm()
        total_norm += param_norm.item() ** 2

    if (
        total_norm == float("inf")
        or total_norm == -float("inf")
        or total_norm != total_norm
    ):
        total_norm = -1

    return total_norm

def get_param_index(param, param_list):
    param_list = list(param_list)
    for idx, p in enumerate(param_list):
        if p is param:
            return idx
    print("no corresponding parameter found!")

