def select(df: PandasDataFrame, columns: LazyColumns) -> PandasDataFrame:
    _check_type(columns, {list, str})
    columns = [columns] if isinstance(columns, str) else columns
    if len(set(columns)) != len(columns):
        raise KeyError(f"column keys must be unique")
    bad_columns = list(set(columns) - set(df.columns))
    if bad_columns and len(bad_columns) == 1:
        raise KeyError(f"column key: {bad_columns} is invalid")
    if bad_columns and len(bad_columns) > 1:
        raise KeyError(f"column keys: {bad_columns} are invalid")
    df = df[columns]
    return df

def denix(df: PandasDataFrame, columns: LazyColumns | None = None) -> PandasDataFrame:
    _check_type(columns, {list, str, None})
    columns = [columns] if isinstance(columns, str) else columns
    if isinstance(columns, list):
        bad_keys = set(columns).difference(df.columns)
        if bad_keys:
            if len(bad_keys) == 1:
                message = f"columns argument contains invalid key {bad_keys}"
            else:
                message = f"columns argument contains invalid keys {bad_keys}"
            raise KeyError(message)
    df = df.dropna(subset=columns)
    df = df.reset_index(drop=True)
    return df

def fill(
    df: PandasDataFrame,
    columns: LazyColumns | None = None,
    direction: Direction | None = None,
    constant: Value | None = None,
) -> PandasDataFrame:
    _check_type(columns, {list, str, None})
    _check_type(direction, {str, None})
    columns = [columns] if isinstance(columns, str) else columns
    if (direction != None) and (constant != None):
        raise ValueError("either direction OR constant must be None")
    if (direction == None) and (constant == None):
        raise ValueError("either direction OR constant must not be None")
    if direction != None:
        if not (direction in ["down", "up"]):
            raise ValueError("must be one of {'down', 'up'}")
        method = {"down": "ffill", "up": "bfill"}.get(direction)
        value = None
    if constant != None:
        value = constant
        method = None
    df = df.copy()
    if columns:
        df[columns] = df[columns].fillna(value=value, method=method)  # type: ignore
    else:
        df = df.fillna(value=value, method=method)  # type: ignore
    return df

def gather(
    df: PandasDataFrame | PandasGroupedFrame,
    columns: Columns | None = None,
    beside: LazyColumns | None = None,
    into: tuple[Column, Column] = ("variable", "value"),
) -> PandasDataFrame:
    _check_type(columns, {list, None})
    _check_type(beside, {str, list, None})
    _check_type(into, tuple)
    if (columns == None) and (beside != None) and isinstance(df, PandasDataFrame):
        warnings.warn(
            "Marked for removal, please use `df.group(...).gather(...)` instead",
            FutureWarning,
        )
    if not (isinstance(into, tuple) and (len(into) == 2)):
        raise TypeError("must be tuple[str, str]")
    if into[0] == into[1]:
        raise TypeError("must be unique")
    if isinstance(df, PandasGroupedFrame):
        if (into[0] in df.obj.columns) or (into[1] in df.obj.columns):  # type: ignore
            raise ValueError("must not be an existing column key")
        if columns != None:
            raise ValueError("columns is incompatible with group+gather")
        if beside != None:
            raise ValueError("beside is incompatible with group+gather")
        df = _grouped_melt(df, into)
        return df
    if (into[0] in df.columns) or (into[1] in df.columns):
        raise ValueError("must not be an existing column key")
    if (columns != None) and (beside != None):
        raise ValueError("columns OR beside must be None")
    if (columns == None) and (beside == None):
        id_vars = []
        value_vars = list(df.columns)
    if isinstance(beside, str):
        beside = [beside]
    if isinstance(beside, list):
        id_vars = beside
        value_vars = [col for col in df.columns if col not in id_vars]
    if isinstance(columns, list):
        id_vars = [col for col in df.columns if col not in columns]
        value_vars = columns
    df = _melt(df, id_vars, value_vars, into)  # pyright: ignore[reportUnboundVariable]
    return df

def split(
    df: PandasDataFrame, column: Column, into: Columns, sep: str, drop: bool = True
) -> PandasDataFrame:
    _check_type(column, str)
    _check_type(into, list)
    _check_type(sep, str)
    _check_type(drop, bool)
    if len(into) != len(set(into)):
        raise KeyError("into keys must be unique")
    if (column in into) and (not drop):
        raise KeyError("into keys must be unique")
    bad_keys = set(df.columns).difference(set([column])).intersection(set(into))
    if bad_keys:
        raise KeyError("into keys must be unique")
    columns = {uuid.uuid4().hex: col for col in into}
    temp = list(columns.keys())
    df = df.copy()
    df[temp] = df[column].str.split(sep, expand=True)
    if drop:
        df = df.drop(column, axis=1)
    df = df.rename(columns=columns)
    return df

def rename(df: PandasDataFrame, columns: dict[OldColumn, NewColumn]) -> PandasDataFrame:
    _check_type(columns, dict)
    cv = columns.values()
    _check_values(cv, str)
    if len(set(cv)) != len(cv):
        raise KeyError("columns must be unique")
    missing_keys = set(columns.keys()) - set(df.columns)
    if missing_keys and len(missing_keys) == 1:
        raise KeyError(f"column key ({missing_keys}) is invalid")
    if missing_keys and len(missing_keys) > 1:
        raise KeyError(f"column keys ({missing_keys}) are invalid")
    df = df.rename(columns=columns)
    return df

def filter(df: PandasDataFrame, func: Func) -> PandasDataFrame:
    if not callable(func):
        raise TypeError("must be Func")
    df = df.loc[func]  # type: ignore
    df = df.reset_index(drop=True)
    return df

def replace(
    df: PandasDataFrame, over: dict[Column, dict[OldValue, NewValue]]
) -> PandasDataFrame:
    _check_type(over, dict)
    bad_columns = list(set(over.keys()) - set(df.columns))
    if bad_columns and len(bad_columns) == 1:
        raise KeyError(f"column key: {bad_columns} is invalid")
    if bad_columns and len(bad_columns) > 1:
        raise KeyError(f"column keys: {bad_columns} are invalid")
    df = df.replace(over)
    return df

