            NumpyType("int64"): int,
            NumpyType("float64"): float,
            NumpyType("bool"): bool,
            NumpyType("datetime64"): DateTime,
        }
        raw_types = dict(self._data.dtypes)
        clean_types = {}
        for column in self.columns:
