def export_history(self, location: str):
        assert os.path.exists(location)

        fpath = os.path.join(location, f"epoch-{str(time.time())}.json")

        def exp_to_dict(exp):
            {k: v.cpu().tolist() for k, v in exp.__dict__.items()}

        data = [exp_to_dict(exp) for exp in self.history]
        with open(fpath, "w") as f:
            f.write(json.dumps(data, indent=2))

def parse_result(result):
    out = {}
    for k, v in result.items():
        if isinstance(v, (int, float)) and not k.startswith("config.") and k not in ray_info:
            out[k] = v

    return out

def __call__(self, statement_string: str):
        """
        Evaluation Function for the interpreter.
        args:
            statement_string (str) : Statement String
        """
        try:
            return eval(statement_string)  # Adding an exception to unparsable strings
        except:
            return "ERROR"

def get_optimizer_class(name: OptimizerName):
    """
    Returns the optimizer class with the given name

    Args:
        name (str): Name of the optimizer as found in `OptimizerNames`
    """
    if name == OptimizerName.ADAM:
        return torch.optim.Adam
    if name == OptimizerName.ADAMW:
        return torch.optim.AdamW
    if name == OptimizerName.ADAM_8BIT_BNB.value:
        try:
            from bitsandbytes.optim import Adam8bit

            return Adam8bit
        except ImportError:
            raise ImportError(
                "You must install the `bitsandbytes` package to use the 8-bit Adam. "
                "Install with: `pip install bitsandbytes`"
            )
    if name == OptimizerName.ADAMW_8BIT_BNB.value:
        try:
            from bitsandbytes.optim import AdamW8bit

            return AdamW8bit
        except ImportError:
            raise ImportError(
                "You must install the `bitsandbytes` package to use 8-bit AdamW. "
                "Install with: `pip install bitsandbytes`"
            )
    if name == OptimizerName.SGD.value:
        return torch.optim.SGD
    supported_optimizers = [o.value for o in OptimizerName]
    raise ValueError(f"`{name}` is not a supported optimizer. " f"Supported optimizers are: {supported_optimizers}")

def get_delta_model_class(model_type: str):
    if not HAS_OPENDELTA:
        raise ValueError("OpenDelta package required to train with delta models. https://github.com/thunlp/OpenDelta.")
    delta_models = {
        "bitfit": BitFitModel,
        "adapter": AdapterModel,
        "prefix": PrefixModel,
        "lora": LoraModel,
        "softprompt": SoftPromptModel,
    }
    return delta_models[model_type]

def _trainer_unavailble(name):
        def log_error(*args, **kwargs):
            raise ImportError(f"Unable to import NeMo so {name} is unavailable")

        return register_trainer(name)(log_error)

@pytest.mark.parametrize(
    "model_name",
    [
        "EleutherAI/gpt-j-6B",
        "EleutherAI/gpt-neox-20b",
        "facebook/opt-1.3b",
        "bigscience/bloom-560m",
        "google/flan-t5-large",
    ],
)
def test_parse_delta_kwargs(model_name):
    config = transformers.AutoConfig.from_pretrained(model_name)

    modified_modules_dict = modeling_utils.MODIFIED_MODULES_DICT[config.model_type]
    for default_modifier, default_modified_modules in modified_modules_dict.items():
        delta_type, delta_kwargs = modeling_utils.parse_delta_kwargs(
            delta_kwargs={"delta_type": "lora", "modified_modules": default_modifier},
            config=config,
            num_layers_unfrozen=4,
        )
        # Ensure the parsed module regex patterns capture the default module names
        for kwarg_mod, default_mod in zip(delta_kwargs["modified_modules"], default_modified_modules):
            assert kwarg_mod.endswith(
                default_mod
            ), f"Parsed modified module `{kwarg_mod}` should contain the trlx default `{default_mod}`"
        assert delta_type == "lora", "Delta type should be lora"

    # Ensure the defaults don't get used if the user specifies a list of `modified_modules`
    delta_type, delta_kwargs = modeling_utils.parse_delta_kwargs(
        delta_kwargs={"delta_type": "lora", "modified_modules": ["a", "b"]},
        config=config,
        num_layers_unfrozen=2,
    )
    for kwarg_mod in delta_kwargs["modified_modules"]:
        assert kwarg_mod.endswith("a") or kwarg_mod.endswith("b"), "Parsed modified module should contain ['a', 'b']"

