        )

def _get_yaml_filepaths(dir: str) -> List[str]:
    """Returns a list of `yml` filepaths in `dir`."""
    filepaths = []
    for file in os.listdir(dir):
        if file.endswith(".yml"):
            filepaths.append(os.path.join(dir, file))
    return filepaths

def _get_config_dirs(dir: str, config_dir_name: str = "configs") -> List[str]:
    """Returns all sub-directories of `dir` named `configs`."""
    config_dirs = []
    for root, dirs, _ in os.walk(dir):
        for d in dirs:
            if d == config_dir_name:
                config_dirs.append(os.path.join(root, d))
    return config_dirs

def get_git_tag() -> Tuple[str, str]:
    """
    Returns commit's short hash and date
    """
    try:
        output = subprocess.check_output("git log --format='%h/%as' -n1".split())
        branch = subprocess.check_output("git rev-parse --abbrev-ref HEAD".split())
        return branch.decode()[:-1], output.decode()[1:-2]
    except subprocess.CalledProcessError:
        return "unknown", "unknown"

def get_lock(self):
        if _tqdm_active:
            return tqdm_lib.tqdm.get_lock()

